import frappe

SCRIPT = "(function(){\n    'use strict';\n\n    var btnDownload = root_element.getElementById('tmo-download');\n    var table = root_element.getElementById('tmo-table');\n    var tbody = root_element.getElementById('tmo-tbody');\n    var empty = root_element.getElementById('tmo-empty');\n    var updated = root_element.getElementById('tmo-updated');\n\n    if (!tbody) return;\n\n    /* Default-date helper no longer needed here — the \"TMS Filter Bar\" block owns default dates:\n    function fmtDate(d) {\n        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');\n    }\n    */\n\n    function dmy(value) {\n        return value ? String(value).slice(0, 10).split('-').reverse().join('-') : '';\n    }\n\n    function money(value) {\n        var n = parseFloat(value) || 0;\n        var sign = n < 0 ? '− ' : '';\n        return sign + '₹' + Math.abs(n).toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 });\n    }\n\n    function esc(value) {\n        return frappe.utils.escape_html(value || '');\n    }\n\n    // Last values broadcast by the shared \"TMS Filter Bar\" block. Kept separate from\n    // what was actually sent so that un-ticking Show All can restore them.\n    var _filter = { from_date:'', to_date:'', company:'', branch:'' };\n    var showAll = false;\n    var dataRows = [];\n\n    function renderRows(rows) {\n        dataRows = (rows || []).slice();\n        tbody.innerHTML = '';\n\n        if (!dataRows.length) {\n            table.style.display = 'none';\n            empty.style.display = '';\n            if (updated) updated.textContent = 'Updated ' + new Date().toLocaleTimeString();\n            return;\n        }\n\n        table.style.display = '';\n        empty.style.display = 'none';\n\n        dataRows.forEach(function (row, index) {\n            var tr = document.createElement('tr');\n            tr.innerHTML =\n                '<td style=\"padding:9px 12px;color:var(--text-muted);border-bottom:1px solid var(--border-color);\">' + (index + 1) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;\">' + dmy(row.trip_date) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;\"><a href=\"#\" class=\"tmo-trip-link\" data-name=\"' + esc(row.name) + '\" style=\"color:var(--primary,#2196F3);text-decoration:none;font-weight:600;\">' + esc(row.trip_no) + '</a></td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);min-width:180px;\">' + esc(row.origin_city) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);min-width:180px;\">' + esc(row.destination_city) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;\">' + esc(row.lr_no) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);white-space:nowrap;\">' + esc(row.vehicle_no) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;\">' + money(row.freight) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;\">' + money(row.approved_addl_amount) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;font-weight:600;\">' + money(row.total_trip_amount) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#e17055;\">' + (parseFloat(row.brokerage_amount)||0 ? money(row.brokerage_amount) : '—') + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#e17055;\">' + (parseFloat(row.broker_lr)||0 ? money(row.broker_lr) : '—') + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#e17055;\">' + (parseFloat(row.tds_amount)||0 ? money(row.tds_amount) : '—') + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;font-weight:600;\">' + money(row.net_receive_amount) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;color:#00b894;font-weight:700;\">' + money(row.amount_received) + '</td>' +\n                '<td style=\"padding:9px 12px;border-bottom:1px solid var(--border-color);text-align:right;white-space:nowrap;font-weight:700;color:' + ((parseFloat(row.balance_amt)||0) > 0.01 ? '#d32f2f' : '#00b894') + ';\">' + money(row.balance_amt) + '</td>';\n\n            tr.querySelector('.tmo-trip-link').addEventListener('click', function (e) {\n                e.preventDefault();\n                frappe.set_route('Form', 'Trip', this.dataset.name);\n            });\n\n            tbody.appendChild(tr);\n        });\n\n        if (updated) updated.textContent = 'Updated ' + new Date().toLocaleTimeString();\n    }\n\n    function fetchData(fromDate, toDate, company, branch) {\n        frappe.call({\n            method: 'logicore.logicore.api.get_trip_other_summary',\n            args: {\n                from_date: fromDate || '',\n                to_date:   toDate   || '',\n                company:   company  || '',\n                branch:    branch   || ''\n            },\n            callback: function (r) {\n                renderRows(r && r.message ? r.message : []);\n            },\n            error: function () {\n                renderRows([]);\n            }\n        });\n    }\n\n    function applyFilter() {\n        if (showAll) {\n            fetchData('', '', '', '');\n        } else {\n            fetchData(_filter.from_date, _filter.to_date, _filter.company, _filter.branch);\n        }\n    }\n\n    function downloadCsv() {\n        if (!dataRows.length) return;\n        var header = ['#', 'Date', 'Trip No', 'Origin City', 'Destination City', 'LR No', 'Vehicle No', 'Freight', 'Total Approved Amount', 'Total Trip Cost', 'Brokerage', 'Broker LR', 'TDS', 'Net Receive Amount', 'Amt Received', 'Balance Amt'];\n        var lines = [header.join(',')];\n        dataRows.forEach(function (row, index) {\n            lines.push([\n                index + 1,\n                '\"' + String(row.trip_date || '').replace(/\"/g, '\"\"') + '\"',\n                '\"' + String(row.trip_no || '').replace(/\"/g, '\"\"') + '\"',\n                '\"' + String(row.origin_city || '').replace(/\"/g, '\"\"') + '\"',\n                '\"' + String(row.destination_city || '').replace(/\"/g, '\"\"') + '\"',\n                '\"' + String(row.lr_no || '').replace(/\"/g, '\"\"') + '\"',\n                '\"' + String(row.vehicle_no || '').replace(/\"/g, '\"\"') + '\"',\n                parseFloat(row.freight) || 0,\n                parseFloat(row.approved_addl_amount) || 0,\n                parseFloat(row.total_trip_amount) || 0,\n                parseFloat(row.brokerage_amount) || 0,\n                parseFloat(row.broker_lr) || 0,\n                parseFloat(row.tds_amount) || 0,\n                parseFloat(row.net_receive_amount) || 0,\n                parseFloat(row.amount_received) || 0,\n                parseFloat(row.balance_amt) || 0\n            ].join(','));\n        });\n\n        var blob = new Blob([lines.join('\\n')], { type: 'text/csv' });\n        var url = URL.createObjectURL(blob);\n        var a = document.createElement('a');\n        a.href = url;\n        a.download = showAll\n            ? 'trip_other_all.csv'\n            : 'trip_other_' + _filter.from_date + '_to_' + _filter.to_date + '.csv';\n        document.body.appendChild(a);\n        a.click();\n        document.body.removeChild(a);\n        URL.revokeObjectURL(url);\n    }\n\n    var cbShowAll = root_element.getElementById('tmo-show-all');\n    if (cbShowAll) {\n        cbShowAll.checked = showAll;\n        cbShowAll.addEventListener('change', function() {\n            showAll = this.checked;\n            applyFilter();\n        });\n    }\n\n    window.addEventListener('tms-filter-changed', function(e) {\n        var d = (e && e.detail) || {};\n        _filter.from_date = d.from_date || '';\n        _filter.to_date   = d.to_date   || '';\n        _filter.company   = d.company   || '';\n        _filter.branch    = d.branch    || '';\n        // A new filter selection always wins over Show All — untick it so the\n        // table follows the shared filter again.\n        showAll = false;\n        if (cbShowAll) cbShowAll.checked = false;\n        applyFilter();\n    });\n\n    btnDownload.addEventListener('click', downloadCsv);\n}());"


def run():
	doc = frappe.get_doc("Custom HTML Block", 'TMS Trip Other')
	doc.script = SCRIPT
	doc.save(ignore_permissions=True)
	frappe.db.commit()
	print('Updated TMS Trip Other block')
